import { expect } from '@playwright/test';
import type { Page, Response } from '@playwright/test';

export async function fillOwnerForm(page: Page, firstName: string, lastName: string, address: string, city: string, telephone: string) {
    await page.locator("#firstName").fill(firstName);
    await page.locator("#lastName").fill(lastName);
    await page.locator("#address").fill(address);
    await page.locator("#city").fill(city);
    await page.locator("#telephone").fill(telephone);
}

export async function fillOwnerEmail(page: Page, email: string) {
    await page.locator("#email").fill(email);
}

export async function submitOwnerForm(page: Page): Promise<Response> {
    await expect(page.getByRole("button", { name: "Add Owner" })).toBeEnabled();
    const responsePromise = page.waitForResponse("**/petclinic/api/owners**");
    await page.getByRole("button", { name: "Add Owner" }).click();
    return await responsePromise;
}

export async function openOwnerFromList(page: Page, ownerName: string) {
    await page.locator("#ownersTable").getByRole("link", { name: ownerName }).click();
}

export async function openOwnerEditForm(page: Page) {
    await page.getByRole("button", { name: "Edit Owner" }).click();
}

export async function updateOwnerEmail(page: Page, email: string) {
    await page.locator("#email").fill(email);
    await page.getByRole("button", { name: "Update Owner" }).click();
}
